// Each executable source line has an authored explanation. The builder rejects gaps.
const files = {};
function file(name, path, purpose, caller, analogy, checks) {
  const f = {name, path, purpose, caller, analogy, checks, notes:{}};
  files[name] = f;
  return (line, what, why, example = '', caution = '') => {
    if (f.notes[line]) throw Error(`Duplicate annotation ${name}:${line}`);
    f.notes[line] = {what, why, example, caution};
  };
}
