function errorResponse(status, responseLine, headerLine, openLine, writeLine, returnLine, message, reason) {
  n(responseLine, `Store the ${message} message in a local String named response.`, `This branch was selected because ${reason}; the next lines send that one error body.`, '', 'A local response declared inside this branch is different from response variables in other branches.');
  n(headerLine, `Send HTTP ${status} with response.getBytes().length as the body byte count.`, 'The client needs the error status and encoded body length before the body is written.', 'getBytes encodes text; .length is the resulting byte-array length.');
  n(openLine,'Acquire this error response\'s OutputStream in try-with-resources.','The handler must write the body and close its stream even if writing fails.');
  n(writeLine,'Encode the response String and write those bytes to the error body.','Headers alone do not send the promised error text.','The same default charset is used for the length and body conversion.');
  if(returnLine) n(returnLine,'Return from handle after sending this rejection.',`Because ${reason}, this request must not reach subsequent parsing, disk storage or share registration.`);
}
